def W(s): return re.sub(r"\{([^}]*)\}", lambda m: "⁦" + m.group(1) + "⁩", s)
def O(o): o = W(o); return o if re.search(r"[֐-׿]", o) or o.startswith("⁦") else "⁦" + o + "⁩"
def Q(topic, q, opts, ans, expl, sc): return (topic, W(q), [O(o) for o in opts], ans, W(expl), sc)

_TXT = TXT
def TXT(*lines, s=None):                                                # number cards as big as the frame allows
    wide = lambda l: len(l) + sum(l.count(c) for c in "△≅∼∠⊥∥")         # these symbols are drawn wider
    return _TXT(*lines, s=s or min(27, (70 if len(lines) < 3 else 57) / len(lines), 230 / max(wide(l) for l in lines)))

def SC(es, *lines):
    """The objects on top (one or a few emoji), the given numbers or words under them."""
    if isinstance(es, str): es = [es]
    k = len(es); es_s = 32 if k == 1 else 26; step = 22
    top = [(e, round(50 + (j - (k - 1) / 2) * step, 1), 24, es_s) for j, e in enumerate(es)]
    n = len(lines); z = min(20, 15 if n > 1 else 20, 150 / max(len(l) for l in lines))
    if n == 1: return [(e, x, 30, 36 if k == 1 else 28) for e, x, _, _ in top] + [(lines[0], 50, 76, round(z))]
    return top + [(l, 50, round(50 + 42 * (i + .5) / n, 1), round(z)) for i, l in enumerate(lines)]

def COUNTS(*rows):
    """Balls in a bag: COUNTS(("🔴", 3), ("🔵", 5))."""
    return COUNT(*rows)

def _w(n, s): return (n * .6 + .8) * s / 1.6
def TAB(*rows):
    """A small table, Hebrew-style: the row name on the right, the values to its left."""
    n, k = len(rows), len(rows[0]) - 1; ys = {1: [45], 2: [32, 64], 3: [20, 43, 66]}[n]
    hl, vl = max(len(r[0]) for r in rows), max(len(v) for r in rows for v in r[1:])
    for s in range(22, 9, -1):
        hw, vw = _w(hl, s), _w(vl, s); step = vw + 4; total = hw + 5 + step * (k - 1) + vw
        if total <= 90: break
    right = 50 + total / 2; hx = right - hw / 2; x0 = right - hw - 5 - vw / 2
    out = []
    for r, y in zip(rows, ys):
        out.append((r[0], round(hx, 1), y, s))
        out += [(v, round(x0 - i * step, 1), y, s) for i, v in enumerate(r[1:])]
    return out

def GRAPH(ys, xs=(0, 1, 2, 3)):
    """Points of a line: red dots (height = y), the x values under them, the axis names."""
    lo, hi, k = min(ys), max(ys), len(xs)
    px = [16 + i * (76 - 16) / (k - 1) for i in range(k)]
    py = [48 if hi == lo else 76 - (y - lo) / (hi - lo) * 48 for y in ys]
    out = [("🔴", round(x, 1), round(y, 1), 10) for x, y in zip(px, py)]
    out += [(str(v), round(x, 1), 91, 10) for v, x in zip(xs, px)]
    return out + [("y", 8, 12, 12), ("x", 94, 91, 12)]

def NL(p, full, right):
    """A number line around p: the circle at p (🔴 included, ⭕ not included), blue dots towards the solutions."""
    out = [(str(v), 14 + 18 * i, 76, 13) for i, v in enumerate(range(p - 2, p + 3))]
    out.append(("🔴" if full else "⭕", 50, 44, 16))
    d = 1 if right else -1
    out += [("🔵", 50 + d * 10 * j, 44, 10) for j in range(1, 4)]
    out.append(("➡️" if right else "⬅️", 50 + d * 42, 44, 15))
    return out

def LINES(ys1, ys2, xs=(0, 1, 2, 3)):
    """Two lines as dots (🔴 and 🔵) over the x values; where they meet (same y) a ⭐."""
    lo, hi, k = min(ys1 + ys2), max(ys1 + ys2), len(xs)
    px = [16 + i * (84 - 16) / (k - 1) for i in range(k)]
    Y = lambda y: round(78 - (y - lo) / (hi - lo) * 64, 1)
    out = []
    for x, a, b in zip(px, ys1, ys2):
        out += [("⭐", round(x, 1), Y(a), 13)] if a == b else [("🔴", round(x, 1), Y(a), 9), ("🔵", round(x, 1), Y(b), 9)]
    return out + [(str(v), round(x, 1), 92, 10) for v, x in zip(xs, px)]

def BUY(row1, p1, row2, p2):
    """Two purchases: the things on the right, '=' and the price on the left."""
    out = []
    for es, p, y in ((row1, p1, 28), (row2, p2, 72)):
        out += [(e, 92 - 10 * j, y, 16) for j, e in enumerate(es)]
        out += [("=", 38, y, 16), (p, 19, y, 16)]
    return out

